unsigned __int128 parse_u128_decimal(const std::string& text) {
    unsigned __int128 value = 0;
    for (const char c : text) {
        if (c < '0' || c > '9') {
            continue;
        }
        value = (value * 10) + static_cast<unsigned>(c - '0');
    }
    return value;
}

std::string u128_to_decimal(unsigned __int128 value) {
    if (value == 0) {
        return "0";
    }
    std::string out;
    while (value > 0) {
        const unsigned digit = static_cast<unsigned>(value % 10);
        out.push_back(static_cast<char>('0' + digit));
        value /= 10;
    }
    std::reverse(out.begin(), out.end());
    return out;
}

py::int_ py_int_from_decimal(const std::string& text) {
    PyObject* obj = PyLong_FromString(text.c_str(), nullptr, 10);
    if (obj == nullptr) {
        throw py::error_already_set();
    }
    return py::reinterpret_steal<py::int_>(obj);
}

std::string py_object_decimal_string(const py::object& obj) {
    py::object text = py::str(obj);
    return py::cast<std::string>(text);
}

struct Pcg64State {
    unsigned __int128 state = 0;
    unsigned __int128 inc = 0;
    uint32_t has_uint32 = 0;
    uint32_t uinteger = 0;
    bool valid = false;
};

Pcg64State meta_pcg64_state(const py::dict& metadata, const char* name) {
    Pcg64State out;
    if (!metadata.contains(name)) {
        return out;
    }
    try {
        py::object raw = py::reinterpret_borrow<py::object>(metadata[py::str(name)]);
        if (raw.is_none()) {
            return out;
        }
        py::dict state_dict = raw.cast<py::dict>();
        const std::string bitgen = py::cast<std::string>(state_dict[py::str("bit_generator")]);
        if (bitgen != "PCG64") {
            return out;
        }
        py::dict inner = py::reinterpret_borrow<py::object>(state_dict[py::str("state")]).cast<py::dict>();
        out.state = parse_u128_decimal(py_object_decimal_string(py::reinterpret_borrow<py::object>(inner[py::str("state")])));
        out.inc = parse_u128_decimal(py_object_decimal_string(py::reinterpret_borrow<py::object>(inner[py::str("inc")])));
        out.has_uint32 = static_cast<uint32_t>(py::cast<int64_t>(state_dict[py::str("has_uint32")]));
        out.uinteger = static_cast<uint32_t>(py::cast<uint64_t>(state_dict[py::str("uinteger")]));
        out.valid = true;
    } catch (...) {
        out.valid = false;
    }
    return out;
}

Pcg64State pcg64_state_from_pyobject(const py::object& raw) {
    py::dict metadata;
    metadata["state"] = raw;
    return meta_pcg64_state(metadata, "state");
}

py::dict pcg64_state_to_py(const Pcg64State& state) {
    py::dict out;
    py::dict inner;
    out["bit_generator"] = "PCG64";
    inner["state"] = py_int_from_decimal(u128_to_decimal(state.state));
    inner["inc"] = py_int_from_decimal(u128_to_decimal(state.inc));
    out["state"] = inner;
    out["has_uint32"] = static_cast<int64_t>(state.has_uint32);
    out["uinteger"] = static_cast<uint64_t>(state.uinteger);
    return out;
}

uint64_t pcg64_bitgen_next_uint64(void* state);
uint32_t pcg64_bitgen_next_uint32(void* state);
double pcg64_bitgen_next_double(void* state);
uint64_t pcg64_bitgen_next_raw(void* state);

class Pcg64 {
public:
    explicit Pcg64(Pcg64State state) : state_(state) {}

    bool valid() const {
        return state_.valid;
    }

    Pcg64State state() const {
        return state_;
    }

    uint64_t raw64() {
        const unsigned __int128 oldstate = state_.state;
        constexpr unsigned __int128 multiplier =
            (static_cast<unsigned __int128>(2549297995355413924ULL) << 64)
            | static_cast<unsigned __int128>(4865540595714422341ULL);
        state_.state = oldstate * multiplier + state_.inc;
        const unsigned __int128 output_state = state_.state;
        const uint64_t xorshifted = static_cast<uint64_t>((output_state >> 64U) ^ output_state);
        const uint32_t rot = static_cast<uint32_t>(output_state >> 122U);
        if (rot == 0) {
            return xorshifted;
        }
        return (xorshifted >> rot) | (xorshifted << ((64U - rot) & 63U));
    }

    uint32_t raw32() {
        if (state_.has_uint32 != 0) {
            state_.has_uint32 = 0;
            return state_.uinteger;
        }
        const uint64_t raw = raw64();
        state_.uinteger = static_cast<uint32_t>(raw >> 32U);
        state_.has_uint32 = 1;
        return static_cast<uint32_t>(raw & 0xffffffffU);
    }

    uint64_t bounded_uint64(const uint64_t max_value) {
        if (max_value == std::numeric_limits<uint64_t>::max()) {
            return raw64();
        }
        uint64_t mask = max_value;
        mask |= mask >> 1U;
        mask |= mask >> 2U;
        mask |= mask >> 4U;
        mask |= mask >> 8U;
        mask |= mask >> 16U;
        mask |= mask >> 32U;
        uint64_t value = 0;
        do {
            value = raw64() & mask;
        } while (value > max_value);
        return value;
    }

    uint32_t bounded_uint32(const uint32_t max_value) {
        if (max_value == std::numeric_limits<uint32_t>::max()) {
            return raw32();
        }
        uint32_t mask = max_value;
        mask |= mask >> 1U;
        mask |= mask >> 2U;
        mask |= mask >> 4U;
        mask |= mask >> 8U;
        mask |= mask >> 16U;
        uint32_t value = 0;
        do {
            value = raw32() & mask;
        } while (value > max_value);
        return value;
    }

    double double01() {
        const uint64_t raw = raw64();
        return static_cast<double>(raw >> 11U) * (1.0 / 9007199254740992.0);
    }

    uint64_t numpy_interval(const uint64_t max_value) {
        bitgen_t bitgen;
        bitgen.state = this;
        bitgen.next_uint64 = &pcg64_bitgen_next_uint64;
        bitgen.next_uint32 = &pcg64_bitgen_next_uint32;
        bitgen.next_double = &pcg64_bitgen_next_double;
        bitgen.next_raw = &pcg64_bitgen_next_raw;
        return random_interval(&bitgen, max_value);
    }

    float numpy_float32_01() {
        bitgen_t bitgen;
        bitgen.state = this;
        bitgen.next_uint64 = &pcg64_bitgen_next_uint64;
        bitgen.next_uint32 = &pcg64_bitgen_next_uint32;
        bitgen.next_double = &pcg64_bitgen_next_double;
        bitgen.next_raw = &pcg64_bitgen_next_raw;
        return random_standard_uniform_f(&bitgen);
    }

    uint32_t numpy_buffered_bounded_uint32(const uint32_t max_value, int* bcnt, uint32_t* buf) {
        bitgen_t bitgen;
        bitgen.state = this;
        bitgen.next_uint64 = &pcg64_bitgen_next_uint64;
        bitgen.next_uint32 = &pcg64_bitgen_next_uint32;
        bitgen.next_double = &pcg64_bitgen_next_double;
        bitgen.next_raw = &pcg64_bitgen_next_raw;
        uint32_t mask = max_value;
        mask |= mask >> 1U;
        mask |= mask >> 2U;
        mask |= mask >> 4U;
        mask |= mask >> 8U;
        mask |= mask >> 16U;
        return random_buffered_bounded_uint32(&bitgen, 0U, max_value, mask, true, bcnt, buf);
    }

private:
    Pcg64State state_;
};

uint64_t pcg64_bitgen_next_uint64(void* state) {
    return reinterpret_cast<Pcg64*>(state)->raw64();
}

uint32_t pcg64_bitgen_next_uint32(void* state) {
    return reinterpret_cast<Pcg64*>(state)->raw32();
}

double pcg64_bitgen_next_double(void* state) {
    return reinterpret_cast<Pcg64*>(state)->double01();
}

uint64_t pcg64_bitgen_next_raw(void* state) {
    return reinterpret_cast<Pcg64*>(state)->raw64();
}

std::array<float, 4> pcg64_numpy_standard_normal4(Pcg64& rng) {
    bitgen_t bitgen;
    bitgen.state = &rng;
    bitgen.next_uint64 = &pcg64_bitgen_next_uint64;
    bitgen.next_uint32 = &pcg64_bitgen_next_uint32;
    bitgen.next_double = &pcg64_bitgen_next_double;
    bitgen.next_raw = &pcg64_bitgen_next_raw;
    std::array<double, 4> values64{};
    random_standard_normal_fill(&bitgen, static_cast<npy_intp>(values64.size()), values64.data());
    std::array<float, 4> values32{};
    for (size_t i = 0; i < values32.size(); ++i) {
        values32[i] = static_cast<float>(values64[i]);
    }
    return values32;
}

std::vector<float> pcg64_numpy_standard_normal_float32(Pcg64& rng, const int64_t count) {
    if (count <= 0) {
        return {};
    }
    bitgen_t bitgen;
    bitgen.state = &rng;
    bitgen.next_uint64 = &pcg64_bitgen_next_uint64;
    bitgen.next_uint32 = &pcg64_bitgen_next_uint32;
    bitgen.next_double = &pcg64_bitgen_next_double;
    bitgen.next_raw = &pcg64_bitgen_next_raw;
    std::vector<double> values64(static_cast<size_t>(count), 0.0);
    random_standard_normal_fill(&bitgen, static_cast<npy_intp>(values64.size()), values64.data());
    std::vector<float> values32(static_cast<size_t>(count), 0.0f);
    for (size_t i = 0; i < values32.size(); ++i) {
        values32[i] = static_cast<float>(values64[i]);
    }
    return values32;
}

void pcg64_consume_numpy_standard_normal(Pcg64& rng, const int64_t count) {
    if (count <= 0) {
        return;
    }
    bitgen_t bitgen;
    bitgen.state = &rng;
    bitgen.next_uint64 = &pcg64_bitgen_next_uint64;
    bitgen.next_uint32 = &pcg64_bitgen_next_uint32;
    bitgen.next_double = &pcg64_bitgen_next_double;
    bitgen.next_raw = &pcg64_bitgen_next_raw;
    std::vector<double> values(static_cast<size_t>(count), 0.0);
    random_standard_normal_fill(&bitgen, static_cast<npy_intp>(values.size()), values.data());
}

py::dict pcg64_raw_sequence(py::object raw_state, int64_t count) {
    Pcg64State state = pcg64_state_from_pyobject(raw_state);
    TORCH_CHECK(state.valid, "pcg64_raw_sequence requires a PCG64 NumPy bit_generator state");
    Pcg64 rng(state);
    py::list values;
    for (int64_t i = 0; i < count; ++i) {
        values.append(py::int_(rng.raw64()));
    }
    py::dict out;
    out["values"] = values;
    out["state"] = pcg64_state_to_py(rng.state());
    return out;
}

py::dict pcg64_float32_random_sequence(py::object raw_state, int64_t count) {
    Pcg64State state = pcg64_state_from_pyobject(raw_state);
    TORCH_CHECK(state.valid, "pcg64_float32_random_sequence requires a PCG64 NumPy bit_generator state");
    TORCH_CHECK(count >= 0, "float32 random count must be nonnegative");
    Pcg64 rng(state);
    py::list values;
    for (int64_t i = 0; i < count; ++i) {
        values.append(rng.numpy_float32_01());
    }
    py::dict out;
    out["values"] = values;
    out["state"] = pcg64_state_to_py(rng.state());
    return out;
}

int64_t pcg64_numpy_int64_integer(Pcg64& rng, const int64_t high_exclusive);

py::dict pcg64_integer_sequence(py::object raw_state, int64_t high_exclusive, int64_t count) {
    Pcg64State state = pcg64_state_from_pyobject(raw_state);
    TORCH_CHECK(state.valid, "pcg64_integer_sequence requires a PCG64 NumPy bit_generator state");
    TORCH_CHECK(high_exclusive > 0, "integer high bound must be positive");
    TORCH_CHECK(count >= 0, "integer count must be nonnegative");
    Pcg64 rng(state);
    py::list values;
    for (int64_t i = 0; i < count; ++i) {
        values.append(pcg64_numpy_int64_integer(rng, high_exclusive));
    }
    py::dict out;
    out["values"] = values;
    out["state"] = pcg64_state_to_py(rng.state());
    return out;
}

py::dict pcg64_shuffle_indices(py::object raw_state, int64_t count) {
    Pcg64State state = pcg64_state_from_pyobject(raw_state);
    TORCH_CHECK(state.valid, "pcg64_shuffle_indices requires a PCG64 NumPy bit_generator state");
    TORCH_CHECK(count >= 0, "shuffle count must be nonnegative");
    Pcg64 rng(state);
    std::vector<int64_t> values;
    values.reserve(static_cast<size_t>(count));
    for (int64_t i = 0; i < count; ++i) {
        values.push_back(i);
    }
    int64_t draws = 0;
    for (int64_t i = count - 1; i > 0; --i) {
        const int64_t j = static_cast<int64_t>(rng.bounded_uint32(static_cast<uint32_t>(i)));
        draws += 1;
        std::swap(values[static_cast<size_t>(i)], values[static_cast<size_t>(j)]);
    }
    py::list shuffled;
    for (const int64_t value : values) {
        shuffled.append(value);
    }
    py::dict out;
    out["values"] = shuffled;
    out["draws"] = draws;
    out["state"] = pcg64_state_to_py(rng.state());
    return out;
}

py::dict pcg64_standard_normal_sequence(py::object raw_state, int64_t count) {
    Pcg64State state = pcg64_state_from_pyobject(raw_state);
    TORCH_CHECK(state.valid, "pcg64_standard_normal_sequence requires a PCG64 NumPy bit_generator state");
    TORCH_CHECK(count >= 0, "standard normal count must be nonnegative");
    Pcg64 rng(state);
    bitgen_t bitgen;
    bitgen.state = &rng;
    bitgen.next_uint64 = &pcg64_bitgen_next_uint64;
    bitgen.next_uint32 = &pcg64_bitgen_next_uint32;
    bitgen.next_double = &pcg64_bitgen_next_double;
    bitgen.next_raw = &pcg64_bitgen_next_raw;
    std::vector<double> values(static_cast<size_t>(count), 0.0);
    random_standard_normal_fill(&bitgen, static_cast<npy_intp>(values.size()), values.data());
    py::list py_values;
    for (const double value : values) {
        py_values.append(value);
    }
    py::dict out;
    out["values"] = py_values;
    out["state"] = pcg64_state_to_py(rng.state());
    return out;
}

struct PythonRandomState {
    std::array<uint32_t, 624> state{};
    int32_t index = 624;
    bool has_gauss_next = false;
    double gauss_next = 0.0;
    int64_t raw_draws = 0;
    bool valid = false;
};

PythonRandomState python_random_state_from_pyobject(const py::object& raw) {
    PythonRandomState out;
    try {
        if (raw.is_none()) {
            return out;
        }
        py::dict state_dict = raw.cast<py::dict>();
        const int64_t version = py::cast<int64_t>(state_dict[py::str("version")]);
        if (version != 3) {
            return out;
        }
        py::list values = py::reinterpret_borrow<py::object>(state_dict[py::str("state")]).cast<py::list>();
        if (py::len(values) != 624) {
            return out;
        }
        for (size_t i = 0; i < 624; ++i) {
            out.state[i] = static_cast<uint32_t>(py::cast<uint64_t>(values[py::int_(i)]) & 0xffffffffULL);
        }
        out.index = static_cast<int32_t>(py::cast<int64_t>(state_dict[py::str("index")]));
        if (out.index < 0 || out.index > 624) {
            return out;
        }
        py::object gauss = py::reinterpret_borrow<py::object>(state_dict[py::str("gauss_next")]);
        if (!gauss.is_none()) {
            out.has_gauss_next = true;
            out.gauss_next = py::cast<double>(gauss);
        }
        if (state_dict.contains(py::str("raw_draws"))) {
            out.raw_draws = py::cast<int64_t>(state_dict[py::str("raw_draws")]);
            if (out.raw_draws < 0) {
                return PythonRandomState{};
            }
        }
        out.valid = true;
    } catch (...) {
        out.valid = false;
    }
    return out;
}

PythonRandomState meta_python_random_state(const py::dict& metadata, const char* name) {
    if (!metadata.contains(name)) {
        return PythonRandomState{};
    }
    return python_random_state_from_pyobject(py::reinterpret_borrow<py::object>(metadata[py::str(name)]));
}

py::dict python_random_state_to_py(const PythonRandomState& state) {
    py::dict out;
    py::list values;
    for (size_t i = 0; i < 624; ++i) {
        values.append(static_cast<uint64_t>(state.state[i]));
    }
    out["schema_version"] = "python_random_state_v1";
    out["version"] = static_cast<int64_t>(3);
    out["state"] = values;
    out["index"] = static_cast<int64_t>(state.index);
    if (state.has_gauss_next) {
        out["gauss_next"] = state.gauss_next;
    } else {
        out["gauss_next"] = py::none();
    }
    out["raw_draws"] = state.raw_draws;
    return out;
}

class CpythonRandom {
public:
    explicit CpythonRandom(PythonRandomState state) : state_(state) {}

    PythonRandomState state() const {
        return state_;
    }

    uint32_t genrand_uint32() {
        TORCH_CHECK(state_.valid, "CPython random state is invalid");
        if (state_.index >= 624) {
            twist();
        }
        uint32_t y = state_.state[static_cast<size_t>(state_.index++)];
        ++state_.raw_draws;
        y ^= (y >> 11U);
        y ^= (y << 7U) & 0x9d2c5680U;
        y ^= (y << 15U) & 0xefc60000U;
        y ^= (y >> 18U);
        return y;
    }

    double random_double() {
        const uint32_t a = genrand_uint32() >> 5U;
        const uint32_t b = genrand_uint32() >> 6U;
        return (static_cast<double>(a) * 67108864.0 + static_cast<double>(b)) * (1.0 / 9007199254740992.0);
    }

    double gauss(const double mu, const double sigma) {
        double z = 0.0;
        if (state_.has_gauss_next) {
            z = state_.gauss_next;
            state_.has_gauss_next = false;
            state_.gauss_next = 0.0;
        } else {
            constexpr double TWOPI = 6.2831853071795864769252867665590057683943387987502;
            const double x2pi = random_double() * TWOPI;
            const double g2rad = std::sqrt(-2.0 * std::log(1.0 - random_double()));
            z = std::cos(x2pi) * g2rad;
            state_.gauss_next = std::sin(x2pi) * g2rad;
            state_.has_gauss_next = true;
        }
        return mu + z * sigma;
    }

    bool consume_gauss(const double sigma, double* value) {
        TORCH_CHECK(value != nullptr, "consume_gauss output must not be null");
        *value = gauss(0.0, sigma);
        return true;
    }

    uint64_t getrandbits_u64(const int64_t k) {
        TORCH_CHECK(k >= 0 && k <= 64, "native CPython getrandbits helper supports 0 <= k <= 64");
        if (k == 0) {
            return 0ULL;
        }
        if (k <= 32) {
            return static_cast<uint64_t>(genrand_uint32() >> (32 - k));
        }
        uint64_t value = 0ULL;
        int64_t bits_filled = 0;
        int64_t remaining = k;
        while (remaining > 0) {
            const int64_t take = std::min<int64_t>(remaining, 32);
            uint32_t word = genrand_uint32();
            if (take < 32) {
                word >>= (32 - take);
            }
            value |= (static_cast<uint64_t>(word) << bits_filled);
            bits_filled += take;
            remaining -= take;
        }
        return value;
    }

    uint64_t randbelow_u64(const uint64_t n) {
        TORCH_CHECK(n > 0, "randbelow requires n > 0");
        const int64_t k = 64 - static_cast<int64_t>(__builtin_clzll(n));
        uint64_t r = getrandbits_u64(k);
        while (r >= n) {
            r = getrandbits_u64(k);
        }
        return r;
    }

    int64_t randrange_i64(const int64_t start, const int64_t stop) {
        TORCH_CHECK(stop > start, "randrange requires stop > start");
        const uint64_t width = static_cast<uint64_t>(stop - start);
        return start + static_cast<int64_t>(randbelow_u64(width));
    }

    std::vector<int64_t> shuffle_indices(const int64_t count) {
        TORCH_CHECK(count >= 0, "shuffle count must be non-negative");
        std::vector<int64_t> values(static_cast<size_t>(count));
        for (int64_t i = 0; i < count; ++i) {
            values[static_cast<size_t>(i)] = i;
        }
        for (int64_t i = count - 1; i > 0; --i) {
            const int64_t j = static_cast<int64_t>(randbelow_u64(static_cast<uint64_t>(i + 1)));
            std::swap(values[static_cast<size_t>(i)], values[static_cast<size_t>(j)]);
        }
        return values;
    }

private:
    void twist() {
        static constexpr uint32_t MATRIX_A = 0x9908b0dfU;
        static constexpr uint32_t UPPER_MASK = 0x80000000U;
        static constexpr uint32_t LOWER_MASK = 0x7fffffffU;
        for (size_t kk = 0; kk < 624 - 397; ++kk) {
            const uint32_t y = (state_.state[kk] & UPPER_MASK) | (state_.state[kk + 1] & LOWER_MASK);
            state_.state[kk] = state_.state[kk + 397] ^ (y >> 1U) ^ ((y & 1U) ? MATRIX_A : 0U);
        }
        for (size_t kk = 624 - 397; kk < 623; ++kk) {
            const uint32_t y = (state_.state[kk] & UPPER_MASK) | (state_.state[kk + 1] & LOWER_MASK);
            state_.state[kk] = state_.state[kk + (397 - 624)] ^ (y >> 1U) ^ ((y & 1U) ? MATRIX_A : 0U);
        }
        const uint32_t y = (state_.state[623] & UPPER_MASK) | (state_.state[0] & LOWER_MASK);
        state_.state[623] = state_.state[396] ^ (y >> 1U) ^ ((y & 1U) ? MATRIX_A : 0U);
        state_.index = 0;
    }

    PythonRandomState state_;
};

