float clamp01(const float value) {
    if (value < 0.0f) {
        return 0.0f;
    }
    if (value > 1.0f) {
        return 1.0f;
    }
    return value;
}

double canon_genome_double(const double value) {
    if (!std::isfinite(value)) {
        return 0.0;
    }
    const float x32 = static_cast<float>(value);
    const double scaled = static_cast<double>(x32) * 100000000.0;
    return std::nearbyint(scaled) / 100000000.0;
}

float canon_genome_float(const double value) {
    return static_cast<float>(canon_genome_double(value));
}

float safe_norm(const float value, const float denom) {
    if (denom <= 0.0f) {
        return 0.0f;
    }
    return clamp01(value / denom);
}

int64_t python_round_to_int64(const double value) {
    const double floored = std::floor(value);
    const double frac = value - floored;
    if (frac > 0.5) {
        return static_cast<int64_t>(floored) + 1;
    }
    if (frac < 0.5) {
        return static_cast<int64_t>(floored);
    }
    const int64_t base = static_cast<int64_t>(floored);
    return (base % 2 == 0) ? base : base + 1;
}

int64_t pcg64_numpy_float32_index(Pcg64& rng, const int64_t high_exclusive) {
    TORCH_CHECK(high_exclusive > 0, "NumPy-style float32 index requires positive high bound");
    constexpr double scale_24 = 1.0 / 16777216.0;
    const uint32_t raw = rng.raw32();
    int64_t value = static_cast<int64_t>(
        std::floor(static_cast<double>(raw >> 8U) * scale_24 * static_cast<double>(high_exclusive))
    );
    if (value < 0) {
        value = 0;
    } else if (value >= high_exclusive) {
        value = high_exclusive - 1;
    }
    return value;
}

int64_t pcg64_numpy_int64_integer(Pcg64& rng, const int64_t high_exclusive) {
    TORCH_CHECK(high_exclusive > 0, "NumPy-style integer draw requires positive high bound");
    if (high_exclusive == 1) {
        return 0;
    }
    TORCH_CHECK(high_exclusive <= static_cast<int64_t>(std::numeric_limits<uint32_t>::max()) + 1LL, "native integer draw currently supports uint32-sized high bounds");
    const uint32_t range = static_cast<uint32_t>(high_exclusive);
    const uint32_t threshold = static_cast<uint32_t>((0U - range) % range);
    while (true) {
        const uint32_t raw = rng.raw32();
        const uint64_t product = static_cast<uint64_t>(raw) * static_cast<uint64_t>(range);
        const uint32_t leftover = static_cast<uint32_t>(product);
        if (leftover >= threshold) {
            return static_cast<int64_t>(product >> 32U);
        }
    }
}

float movement_cost_norm(const float value, const float lo, const float hi) {
    const float span = hi - lo;
    if (span <= 0.0f) {
        return 0.0f;
    }
    return clamp01((value - lo) / span);
}

torch::Tensor drive_adjusted_logits(
    torch::Tensor logits_policy,
    const torch::Tensor& drives,
    const torch::Tensor& gain,
    const double w_hunger_gather,
    const double w_pain_rest,
    const double w_fatigue_rest,
    const double w_pain_attack,
    const double w_fear_attack
) {
    namespace idx = torch::indexing;
    auto logits = logits_policy.clone();
    logits.index_put_({idx::Slice(), ACT_GATHER}, logits.index({idx::Slice(), ACT_GATHER}) + gain * (w_hunger_gather * drives.index({idx::Slice(), 0})));
    logits.index_put_(
        {idx::Slice(), ACT_REST},
        logits.index({idx::Slice(), ACT_REST}) + gain * (w_pain_rest * drives.index({idx::Slice(), 1}) + w_fatigue_rest * drives.index({idx::Slice(), 2}))
    );
    logits.index_put_(
        {idx::Slice(), ACT_ATTACK},
        logits.index({idx::Slice(), ACT_ATTACK}) - gain * (w_pain_attack * drives.index({idx::Slice(), 1}) + w_fear_attack * drives.index({idx::Slice(), 3}))
    );
    return logits;
}

