    py::dict execute_lifecycle_mutation_cpu() {
        TORCH_CHECK(tensors_.find("slot_to_agent_id") != tensors_.end(), "slot_to_agent_id missing");
        TORCH_CHECK(tensors_.find("slot_tokens") != tensors_.end(), "slot_tokens missing");
        TORCH_CHECK(tensors_.find("alive_mask") != tensors_.end(), "alive_mask missing");
        TORCH_CHECK(tensors_.find("pos_y") != tensors_.end(), "pos_y missing");
        TORCH_CHECK(tensors_.find("pos_x") != tensors_.end(), "pos_x missing");
        TORCH_CHECK(tensors_.find("energy") != tensors_.end(), "energy missing");
        TORCH_CHECK(tensors_.find("health") != tensors_.end(), "health missing");
        TORCH_CHECK(tensors_.find("agent_grid") != tensors_.end(), "agent_grid missing");
        TORCH_CHECK(tensors_.find("mlp_pack") != tensors_.end(), "mlp_pack missing");
        TORCH_CHECK(tensors_.find("gru_pack") != tensors_.end(), "gru_pack missing");
        TORCH_CHECK(tensors_.find("hmem") != tensors_.end(), "hmem missing");
        TORCH_CHECK(tensors_.find("action_cache_token") != tensors_.end(), "action_cache_token missing");
        TORCH_CHECK(tensors_.find("action_cache_cursor") != tensors_.end(), "action_cache_cursor missing");
        TORCH_CHECK(tensors_.find("action_cache_next") != tensors_.end(), "action_cache_next missing");

        auto slot_to_agent_id = tensors_.at("slot_to_agent_id");
        auto slot_tokens = tensors_.at("slot_tokens");
        auto alive_mask = tensors_.at("alive_mask");
        auto pos_y = tensors_.at("pos_y");
        auto pos_x = tensors_.at("pos_x");
        auto energy = tensors_.at("energy");
        auto health = tensors_.at("health");
        auto agent_grid = tensors_.at("agent_grid");
        auto mlp_pack = tensors_.at("mlp_pack");
        auto gru_pack = tensors_.at("gru_pack");
        auto hmem = tensors_.at("hmem");
        auto action_cache_token = tensors_.at("action_cache_token");
        auto action_cache_cursor = tensors_.at("action_cache_cursor");
        auto action_cache_next = tensors_.at("action_cache_next");
        TORCH_CHECK(!slot_to_agent_id.is_cuda() && !slot_tokens.is_cuda() && !alive_mask.is_cuda(), "lifecycle CPU path requires CPU tensors");
        TORCH_CHECK(!pos_y.is_cuda() && !pos_x.is_cuda() && !energy.is_cuda() && !health.is_cuda() && !agent_grid.is_cuda(), "lifecycle CPU path requires CPU tensors");
        TORCH_CHECK(!mlp_pack.is_cuda() && !gru_pack.is_cuda() && !hmem.is_cuda(), "lifecycle CPU path requires CPU policy tensors");

        auto slot_to_agent_id_a = slot_to_agent_id.accessor<int64_t, 1>();
        auto slot_tokens_a = slot_tokens.accessor<int64_t, 1>();
        auto alive_a = alive_mask.accessor<bool, 1>();
        auto y_a = pos_y.accessor<int32_t, 1>();
        auto x_a = pos_x.accessor<int32_t, 1>();
        auto energy_a = energy.accessor<float, 1>();
        auto health_a = health.accessor<float, 1>();
        auto grid_a = agent_grid.accessor<int32_t, 2>();
        auto cache_token_a = action_cache_token.accessor<int64_t, 1>();
        auto cache_cursor_a = action_cache_cursor.accessor<int32_t, 1>();
        auto cache_next_a = action_cache_next.accessor<int32_t, 1>();
        const int64_t slots_n = slot_to_agent_id.size(0);
        const int64_t height = agent_grid.size(0);
        const int64_t width = agent_grid.size(1);
        const float refill_energy = static_cast<float>(0.5 * meta_double(metadata_, "max_energy", 20.0));
        const float refill_health = static_cast<float>(meta_double(metadata_, "start_health", 1.0));

        int64_t deaths = 0;
        int64_t refills = 0;
        int64_t failed_births = 0;
        int64_t slot_reuse = 0;
        int64_t mutation_events = 0;
        for (int64_t slot = 0; slot < slots_n; ++slot) {
            if (!alive_a[slot]) {
                continue;
            }
            if (energy_a[slot] > 0.0f && health_a[slot] > 0.0f) {
                continue;
            }
            const int64_t aid64 = slot_to_agent_id_a[slot];
            const int32_t aid = static_cast<int32_t>(std::max<int64_t>(0, std::min<int64_t>(aid64, std::numeric_limits<int32_t>::max())));
            const int32_t old_y = y_a[slot];
            const int32_t old_x = x_a[slot];
            if (old_y >= 0 && old_y < height && old_x >= 0 && old_x < width && grid_a[old_y][old_x] == aid) {
                grid_a[old_y][old_x] = -1;
            }
            alive_a[slot] = false;
            hmem.select(0, slot).zero_();
            deaths += 1;

            bool placed = false;
            for (int64_t y = 0; y < height && !placed; ++y) {
                for (int64_t x = 0; x < width && !placed; ++x) {
                    if (grid_a[y][x] != -1) {
                        continue;
                    }
                    grid_a[y][x] = aid;
                    y_a[slot] = static_cast<int32_t>(y);
                    x_a[slot] = static_cast<int32_t>(x);
                    placed = true;
                }
            }
            if (!placed) {
                failed_births += 1;
                continue;
            }
            alive_a[slot] = true;
            energy_a[slot] = refill_energy;
            health_a[slot] = refill_health;
            slot_tokens_a[slot] += 1;
            cache_token_a[slot] = -1;
            cache_cursor_a[slot] = -1;
            cache_next_a[slot] = -1;
            hmem.index_put_({slot}, torch::zeros({hmem.size(1)}, hmem.options()));
            if (mlp_pack.size(1) > 0) {
                mlp_pack.index_put_({slot, 0}, mlp_pack.index({slot, 0}) + 1.0e-5);
                mutation_events += 1;
            }
            if (gru_pack.size(1) > 0) {
                gru_pack.index_put_({slot, 0}, gru_pack.index({slot, 0}) - 1.0e-5);
                mutation_events += 1;
            }
            refills += 1;
            slot_reuse += 1;
        }
        event_cursor_ += deaths + refills + failed_births + mutation_events;

        py::dict out;
        out["schema_version"] = "cxxbackbone11_lifecycle_mutation_result_v1";
        out["decision"] = "CXXBACKBONE11-LIFECYCLE-MUTATION-OWNER-ATTEMPT";
        out["executed"] = true;
        out["hidden_fallback"] = false;
        out["native_owner"] = true;
        out["deaths"] = deaths;
        out["refills"] = refills;
        out["failed_births"] = failed_births;
        out["slot_reuse"] = slot_reuse;
        out["mutation_events"] = mutation_events;
        out["event_cursor"] = static_cast<int64_t>(event_cursor_);
        out["blocker"] = "native_lifecycle_microcycle_handles_death_refill_slot_reuse_mutation_but_exact_reproduction_lineage_rng_parity_not_integrated";
        return out;
    }

    py::dict execute_population_attempt_scheduler_cpu(const bool decrement_cooldown) {
        TORCH_CHECK(tensors_.find("slot_to_agent_id") != tensors_.end(), "slot_to_agent_id missing");
        TORCH_CHECK(tensors_.find("alive_mask") != tensors_.end(), "alive_mask missing");
        TORCH_CHECK(tensors_.find("energy") != tensors_.end(), "energy missing");
        TORCH_CHECK(tensors_.find("health") != tensors_.end(), "health missing");
        TORCH_CHECK(tensors_.find("injury") != tensors_.end(), "injury missing");
        TORCH_CHECK(tensors_.find("scar") != tensors_.end(), "scar missing");
        TORCH_CHECK(tensors_.find("repro_cooldown") != tensors_.end(), "repro_cooldown missing");
        TORCH_CHECK(tensors_.find("repro_threshold") != tensors_.end(), "repro_threshold missing");

        auto slot_to_agent_id = tensors_.at("slot_to_agent_id");
        auto energy = tensors_.at("energy");
        auto health = tensors_.at("health");
        auto injury = tensors_.at("injury");
        auto scar = tensors_.at("scar");
        auto cooldown = tensors_.at("repro_cooldown");
        auto threshold = tensors_.at("repro_threshold");
        TORCH_CHECK(!slot_to_agent_id.is_cuda() && !energy.is_cuda() && !cooldown.is_cuda(), "population scheduler requires CPU tensors");
        TORCH_CHECK(!health.is_cuda() && !injury.is_cuda() && !scar.is_cuda() && !threshold.is_cuda(), "population scheduler requires CPU tensors");
        TORCH_CHECK(slot_to_agent_id.scalar_type() == torch::kInt64, "slot_to_agent_id must be int64");
        TORCH_CHECK(energy.scalar_type() == torch::kFloat32 && threshold.scalar_type() == torch::kFloat32, "energy/threshold must be float32");
        TORCH_CHECK(health.scalar_type() == torch::kFloat32 && injury.scalar_type() == torch::kFloat32 && scar.scalar_type() == torch::kFloat32, "health/injury/scar must be float32");
        TORCH_CHECK(cooldown.scalar_type() == torch::kInt32, "repro_cooldown must be int32");

        auto aid_a = slot_to_agent_id.accessor<int64_t, 1>();
        auto energy_a = energy.accessor<float, 1>();
        auto health_a = health.accessor<float, 1>();
        auto injury_a = injury.accessor<float, 1>();
        auto scar_a = scar.accessor<float, 1>();
        auto cooldown_a = cooldown.accessor<int32_t, 1>();
        auto threshold_a = threshold.accessor<float, 1>();
        const py::object injury_gate_obj = metadata_.contains("injury_repro_block")
            ? py::reinterpret_borrow<py::object>(metadata_[py::str("injury_repro_block")])
            : py::none();
        const py::object scar_gate_obj = metadata_.contains("scar_repro_block")
            ? py::reinterpret_borrow<py::object>(metadata_[py::str("scar_repro_block")])
            : py::none();
        const bool injury_gate_enabled = meta_bool(metadata_, "enable_injury", false) && !injury_gate_obj.is_none();
        const bool scar_gate_enabled = meta_bool(metadata_, "enable_scar", false) && !scar_gate_obj.is_none();
        const float injury_gate = injury_gate_enabled ? static_cast<float>(py::cast<double>(injury_gate_obj)) : 0.0f;
        const float scar_gate = scar_gate_enabled ? static_cast<float>(py::cast<double>(scar_gate_obj)) : 0.0f;

        py::list considered_ids;
        py::list eligible_ids;
        py::list cooldown_blocked_ids;
        py::list no_energy_ids;
        py::list injury_blocked_ids;
        py::list scar_blocked_ids;
        int64_t considered = 0;
        int64_t eligible = 0;
        int64_t cooldown_decrements = 0;
        int64_t cooldown_blocked = 0;
        int64_t no_energy = 0;
        int64_t injury_blocked = 0;
        int64_t scar_blocked = 0;
        const auto slots = alive_slots_sorted_by_agent_id();
        for (const int64_t slot : slots) {
            const int64_t aid64 = aid_a[slot];
            if (aid64 < 0) {
                continue;
            }
            if (health_a[slot] <= 0.0f) {
                continue;
            }
            considered += 1;
            considered_ids.append(aid64);
            int32_t cd = cooldown_a[slot];
            if (cd > 0 && decrement_cooldown) {
                cd = std::max<int32_t>(0, static_cast<int32_t>(cd - 1));
                cooldown_a[slot] = cd;
                cooldown_decrements += 1;
            }
            if (cd != 0) {
                cooldown_blocked += 1;
                cooldown_blocked_ids.append(aid64);
                continue;
            }
            if (energy_a[slot] < threshold_a[slot]) {
                no_energy += 1;
                no_energy_ids.append(aid64);
                continue;
            }
            if (injury_gate_enabled && injury_a[slot] > injury_gate) {
                injury_blocked += 1;
                injury_blocked_ids.append(aid64);
                continue;
            }
            if (scar_gate_enabled && scar_a[slot] > scar_gate) {
                scar_blocked += 1;
                scar_blocked_ids.append(aid64);
                continue;
            }
            eligible += 1;
            eligible_ids.append(aid64);
        }

        py::dict out;
        out["schema_version"] = "cxxbackbone16_population_attempt_scheduler_v1";
        out["decision"] = "CXXBACKBONE16-POPULATION-ATTEMPT-SCHEDULER-NATIVE";
        out["executed"] = true;
        out["hidden_fallback"] = false;
        out["native_owner"] = true;
        out["decrement_cooldown"] = decrement_cooldown;
        out["considered"] = considered;
        out["eligible"] = eligible;
        out["cooldown_decrements"] = cooldown_decrements;
        out["cooldown_blocked"] = cooldown_blocked;
        out["no_energy"] = no_energy;
        out["injury_blocked"] = injury_blocked;
        out["scar_blocked"] = scar_blocked;
        out["considered_agent_ids"] = considered_ids;
        out["eligible_agent_ids"] = eligible_ids;
        out["cooldown_blocked_agent_ids"] = cooldown_blocked_ids;
        out["no_energy_agent_ids"] = no_energy_ids;
        out["injury_blocked_agent_ids"] = injury_blocked_ids;
        out["scar_blocked_agent_ids"] = scar_blocked_ids;
        out["blocker"] = "native_scheduler_owns_pre_child_attempt_order_but_mate_spawn_child_mutation_events_remain_python";
        return out;
    }

