            const int64_t step = population_py_rng.randbelow_u64(2) == 0 ? -1 : 1;
            mutation_py_semantic_draws += 1;
            idx = std::max<int32_t>(0, std::min<int32_t>(4, idx + static_cast<int32_t>(step)));
