                    row.append(use_gru_a[child_slot] ? "gru_pack" : "mlp_pack");
                    row.append(mutation.mode);
                    row.append(mutation.draw_count);
                    row.append(mutation.mutated_elements);
                    row.append(static_cast<int64_t>(mutation.pre_hash & 0x7fffffffffffffffULL));
                    row.append(static_cast<int64_t>(mutation.post_hash & 0x7fffffffffffffffULL));
                    mutation_rows.append(row);
