                spawn_row.append(parent_aid);
                spawn_row.append(mate_aid);
                spawn_row.append(spawn_candidate_count);
                spawn_row.append(spawn_draw_start);
                spawn_row.append(spawn_draw_end);
                spawn_row.append(cy);
                spawn_row.append(cx);
