        out["birth_pre_no_mate"] = birth_pre_no_mate;
        out["birth_fail_no_space"] = birth_fail_no_space;
        out["birth_fail_no_mate"] = birth_fail_no_mate;
        out["birth_fail_buffer"] = birth_fail_buffer;
        out["birth_fail_injury_gate"] = birth_fail_injury_gate;
        out["birth_fail_scar_gate"] = birth_fail_scar_gate;
        out["birth_fail_conception"] = birth_fail_conception;
        out["birth_fail_gestation"] = birth_fail_gestation;
        out["no_free_slot"] = no_free_slot;
        out["no_space"] = no_space;
        out["buffer_blocked"] = buffer_blocked;
        out["mutation_events"] = mutation_events;
        out["typed_event_rows"] = static_cast<int64_t>(lifecycle_events.size());
        out["mutation_delta_total"] = mutation_delta_total;
        out["population_birth_noise_rows_consumed"] = population_birth_noise_rows_consumed;
        out["population_exp_prior_noise_rows_consumed"] = population_exp_prior_noise_rows_consumed;
        out["jungle_birth_emission_count"] = jungle_birth_emission_count;
        out["jungle_birth_scent_emitted_total"] = jungle_birth_scent_emitted_total;
        out["jungle_birth_waste_emitted_total"] = jungle_birth_waste_emitted_total;
        out["native_population_standard_normal_rows_generated"] = population_birth_noise_rows_consumed;
        out["python_precomputed_child_random_rows_consumed"] = static_cast<int64_t>(0);
        out["native_runtime_rng_state"] = static_cast<int64_t>(env_numpy_state.state & 0x7fffffffffffffffULL);
        out["parent_energy_debited"] = parent_energy_debited;
        out["child_energy_total"] = child_energy_total;
