            spawn_rng_draws += py::cast<int64_t>(birth_commit[py::str("spawn_rng_draws")]);
            append_list_items(spawn_rows, birth_commit[py::str("spawn_rows")]);
            append_list_items(failed_spawn_rows, birth_commit[py::str("failed_spawn_rows")]);
            append_list_items(child_hash_rows, birth_commit[py::str("child_hash_rows")]);
            append_list_items(child_hash_chain_rows, birth_commit[py::str("child_hash_chain_rows")]);
            append_list_items(child_drive_rows, birth_commit[py::str("child_drive_rows")]);
