            append_list_items(child_slots, birth_commit[py::str("child_slots")]);
            append_list_items(child_positions, birth_commit[py::str("child_positions")]);
            py::dict cycle;
            cycle["tick_offset"] = tick;
            cycle["death_rows"] = tick_deaths;
            cycle["committed_birth_rows"] = tick_committed;
            cycle["failed_birth_rows"] = tick_failed;
            cycle["public_failed_birth_rows"] = tick_public_failed;
            cycle["birth_attempt_rows"] = tick_attempts;
            cycle["mutation_events"] = tick_mutations;
            cycle["typed_death_event_rows"] = tick_death_events;
            cycle["typed_event_rows"] = tick_death_events + tick_birth_events;
            cycle["policy_cache_rows_requested"] = generation[py::str("policy_cache_rows_requested")];
            cycle["policy_cache_rows_hit"] = generation[py::str("policy_cache_rows_hit")];
            cycle["policy_cache_rows_missed"] = generation[py::str("policy_cache_rows_missed")];
            cycle["policy_cache_rows_refilled"] = generation[py::str("policy_cache_rows_refilled")];
