    py::dict execute_generation_patch_with_population_birth_commit_cpu(
        const int64_t generation_index,
        const int64_t steps_per_generation,
        const int64_t max_births
    ) {
        static const std::function<void(int64_t, int64_t, int64_t)> no_inter_tick_control;
        return execute_generation_patch_with_population_birth_commit_controlled_cpu(
            generation_index,
            steps_per_generation,
            max_births,
            no_inter_tick_control,
            true,
            false
        );
    }

    py::dict execute_tick_span_patch_cpu(
        const int64_t span_ticks,
        const int64_t max_births
    ) {
        TORCH_CHECK(span_ticks > 0, "Tick-native Patch span must be positive");
        TORCH_CHECK(
            !meta_bool(metadata_, "native_runtime_wdl_execution_enable", false),
            "Tick-native Patch owner does not yet support WDL absolute-tick scheduling"
        );
        static const std::function<void(int64_t, int64_t, int64_t)> no_inter_tick_control;
        const int64_t generation = meta_int(metadata_, "generation", 0);
        const int64_t start_next_tick = std::max<int64_t>(
            0,
            meta_int(metadata_, "tick", 0)
        );
        py::dict out = execute_generation_patch_with_population_birth_commit_controlled_cpu(
            generation,
            span_ticks,
            max_births,
            no_inter_tick_control,
            false,
            true
        );
        const int64_t next_tick = std::max<int64_t>(
            0,
            meta_int(metadata_, "tick", 0)
        );
        TORCH_CHECK(
            next_tick == start_next_tick + span_ticks,
            "Tick-native Patch span did not commit its requested cursor"
        );
        out["schema_version"] = "eiel_native_tick_span_patch_cpu_v1";
        out["route_identity"] = "tick_native_execution_route_v1";
        out["start_next_tick"] = start_next_tick;
        out["next_tick"] = next_tick;
        out["absolute_tick"] = py::none();
        out["legacy_turnover_interval_ticks"] = py::none();
        out["generation_authority"] = false;
        out["checkpoint_generation_boundary_pending"] = false;
        out["blocker"] = "tick_native_patch_cpu_owner_unqualified_provider_and_b48_paths_remain_closed";
        return out;
    }

