        out["patch_regrowth_multiplier_mean"] = patch_regrowth_multiplier_mean_sum / patch_regrowth_denominator;
        out["patch_regrowth_multiplier_min"] = patch_regrowth_multiplier_min;
        out["patch_regrowth_multiplier_p10"] = patch_regrowth_multiplier_p10_sum / patch_regrowth_denominator;
