        out["patch_waste_regrowth_penalty_mean"] = patch_waste_regrowth_penalty_mean_sum / patch_regrowth_denominator;
        out["patch_waste_regrowth_penalty_max"] = patch_waste_regrowth_penalty_max;
        out["patch_density_regrowth_penalty_mean"] = patch_density_regrowth_penalty_mean_sum / patch_regrowth_denominator;
        out["patch_density_regrowth_penalty_max"] = patch_density_regrowth_penalty_max;
        out["patch_high_waste_regrowth_suppression_frac"] = patch_high_waste_regrowth_suppression_frac_sum / patch_regrowth_denominator;
        out["patch_high_density_regrowth_suppression_frac"] = patch_high_density_regrowth_suppression_frac_sum / patch_regrowth_denominator;
