        out["legacy_behavior_rows_materialized"] = materialize_legacy_behavior_rows;
        if (materialize_legacy_behavior_rows) {
            out["behavior_rows"] = behavior_rows_cpu(generation_index);
        }
        out["spawn_rows"] = spawn_rows;
        out["failed_spawn_rows"] = failed_spawn_rows;
        out["child_hash_rows"] = child_hash_rows;
        out["child_hash_chain_rows"] = child_hash_chain_rows;
        out["child_drive_rows"] = child_drive_rows;
        out["failed_parent_agent_ids"] = failed_parent_agent_ids;
        out["failed_birth_reason_codes"] = failed_birth_reason_codes;
        out["failed_birth_reasons"] = failed_birth_reasons;
        out["mutation_rows"] = mutation_rows;
        out["parent_agent_ids"] = parent_agent_ids;
        out["mate_agent_ids"] = mate_agent_ids;
        out["child_agent_ids"] = child_agent_ids;
        out["child_slots"] = child_slots;
        out["child_positions"] = child_positions;
        out["patch_capability"] = "controlled_resident_cpu_slice_v1";
