    std::vector<int64_t> alive_slots_sorted_by_agent_id() const {
        const auto slot_to_agent_id = tensors_.at("slot_to_agent_id");
        const auto alive_mask = tensors_.at("alive_mask");
        TORCH_CHECK(!slot_to_agent_id.is_cuda() && !alive_mask.is_cuda(), "active CPU application requires CPU slot tensors");
        TORCH_CHECK(slot_to_agent_id.scalar_type() == torch::kInt64, "slot_to_agent_id must be int64");
        TORCH_CHECK(alive_mask.scalar_type() == torch::kBool, "alive_mask must be bool");
        auto aid_a = slot_to_agent_id.accessor<int64_t, 1>();
        auto alive_a = alive_mask.accessor<bool, 1>();
        std::vector<int64_t> slots;
        for (int64_t slot = 0; slot < slot_to_agent_id.size(0); ++slot) {
            if (alive_a[slot] && aid_a[slot] >= 0) {
                slots.push_back(slot);
            }
        }
        std::stable_sort(slots.begin(), slots.end(), [&](const int64_t left, const int64_t right) {
            return aid_a[left] < aid_a[right];
        });
        return slots;
    }

    struct ActiveIdentityRows {
        torch::Tensor agent_ids;
        torch::Tensor slots;
    };

    ActiveIdentityRows active_identity_rows_exact(
        const bool validate_materialized_shadows
    ) const {
        const auto& slot_to_agent_id = tensors_.at("slot_to_agent_id");
        const auto& alive_mask = tensors_.at("alive_mask");
        TORCH_CHECK(
            slot_to_agent_id.scalar_type() == torch::kInt64
                && slot_to_agent_id.dim() == 1
                && slot_to_agent_id.is_contiguous(),
            "slot_to_agent_id must be contiguous int64[slots]"
        );
        TORCH_CHECK(
            alive_mask.scalar_type() == torch::kBool
                && alive_mask.dim() == 1
                && alive_mask.is_contiguous(),
            "alive_mask must be contiguous bool[slots]"
        );
        TORCH_CHECK(
            slot_to_agent_id.device() == alive_mask.device()
                && slot_to_agent_id.size(0) == alive_mask.size(0),
            "slot identity authority dimensions or devices disagree"
        );
        TORCH_CHECK(
            slot_to_agent_id.size(0) <= std::numeric_limits<int32_t>::max(),
            "slot identity authority capacity exceeds int32"
        );
        const auto assigned_mask = slot_to_agent_id.ge(0);
        TORCH_CHECK(
            torch::equal(alive_mask, assigned_mask),
            "alive_mask and slot_to_agent_id partition contradiction"
        );
        auto active_slots_long = torch::nonzero(alive_mask)
                                     .reshape({-1})
                                     .to(torch::kLong)
                                     .contiguous();
        auto unsorted_ids = slot_to_agent_id
                                .index_select(0, active_slots_long)
                                .contiguous();
        auto sorted = torch::sort(unsorted_ids);
        auto agent_ids = std::get<0>(sorted).contiguous();
        auto order = std::get<1>(sorted);
        auto slots = active_slots_long
                         .index_select(0, order)
                         .to(torch::kInt32)
                         .contiguous();
        const int64_t active_count = agent_ids.size(0);
        if (active_count > 1) {
            TORCH_CHECK(
                agent_ids.slice(0, 1, active_count)
                    .gt(agent_ids.slice(0, 0, active_count - 1))
                    .all()
                    .item<bool>(),
                "active biological agent IDs must be strictly increasing and unique"
            );
        }
        auto validate_shadow = [&](
            const char* name,
            const torch::Tensor& expected,
            const c10::ScalarType dtype
        ) {
            const auto found = tensors_.find(name);
            if (found == tensors_.end()) {
                return;
            }
            const auto& shadow = found->second;
            TORCH_CHECK(
                shadow.scalar_type() == dtype
                    && shadow.dim() == 1
                    && shadow.is_contiguous()
                    && shadow.device() == expected.device(),
                name,
                " compatibility shadow has an invalid layout"
            );
            TORCH_CHECK(
                torch::equal(shadow, expected),
                name,
                " compatibility shadow disagrees with slot identity authority"
            );
        };
        if (validate_materialized_shadows) {
            TORCH_CHECK(
                tensors_.find("agent_ids_by_alive_order") != tensors_.end(),
                "compact identity v2 requires agent_ids_by_alive_order"
            );
            validate_shadow(
                "agent_ids_by_alive_order", agent_ids, torch::kInt64
            );
            const bool has_compact_ids =
                tensors_.find("agent_id_to_slot_agent_ids") != tensors_.end();
            const bool has_compact_slots =
                tensors_.find("agent_id_to_slot_slots") != tensors_.end();
            TORCH_CHECK(
                has_compact_ids && has_compact_slots,
                "compact identity v2 requires paired ID and slot tensors"
            );
            validate_shadow(
                "agent_id_to_slot_agent_ids", agent_ids, torch::kInt64
            );
            validate_shadow(
                "agent_id_to_slot_slots", slots, torch::kInt32
            );
        }
        return {agent_ids, slots};
    }

    int64_t slot_for_agent_id_exact_cpu(const int64_t agent_id) const {
        if (agent_id < 0) {
            return -1;
        }
        const auto& slot_to_agent_id = tensors_.at("slot_to_agent_id");
        const auto& alive_mask = tensors_.at("alive_mask");
        TORCH_CHECK(
            !slot_to_agent_id.is_cuda() && !alive_mask.is_cuda(),
            "bounded identity lookup requires CPU slot authority"
        );
        auto ids_a = slot_to_agent_id.accessor<int64_t, 1>();
        auto alive_a = alive_mask.accessor<bool, 1>();
        int64_t resolved_slot = -1;
        for (int64_t slot = 0; slot < slot_to_agent_id.size(0); ++slot) {
            if (alive_a[slot] && ids_a[slot] == agent_id) {
                TORCH_CHECK(
                    resolved_slot < 0,
                    "slot identity authority contains duplicate agent ID"
                );
                resolved_slot = slot;
            }
        }
        return resolved_slot;
    }

    int64_t initialize_flat_default_developmental_stage_exact() {
        auto found = tensors_.find("dev_stage_initialized");
        if (found == tensors_.end()) {
            tensors_["dev_stage_initialized"] = torch::zeros_like(
                tensors_.at("alive_mask"),
                torch::TensorOptions().dtype(torch::kBool).device(torch::kCPU)
            );
            found = tensors_.find("dev_stage_initialized");
        }
        auto initialized = found->second;
        TORCH_CHECK(!initialized.is_cuda(), "dev_stage_initialized must be CPU");
        TORCH_CHECK(initialized.scalar_type() == torch::kBool, "dev_stage_initialized must be bool");
        TORCH_CHECK(initialized.dim() == 1, "dev_stage_initialized must be 1D");
        auto initialized_a = initialized.accessor<bool, 1>();
        int64_t transitions = 0;
        for (const int64_t slot : alive_slots_sorted_by_agent_id()) {
            if (!initialized_a[slot]) {
                initialized_a[slot] = true;
                transitions += 1;
            }
        }
        return transitions;
    }

    std::vector<int64_t> alive_slots_shuffled_by_runner_rng() {
        auto slots = alive_slots_sorted_by_agent_id();
        add_rng_manager_stream_index("metrics", "np", static_cast<int64_t>(slots.size()));
        if (slots.size() <= 1) {
            return slots;
        }
        Pcg64State runner_numpy_state = meta_pcg64_state(metadata_, "native_runtime_numpy_runner_state");
        TORCH_CHECK(runner_numpy_state.valid, "native action order shuffle requires serialized runner NumPy RNG state");
        Pcg64 runner_rng(runner_numpy_state);
        for (int64_t i = static_cast<int64_t>(slots.size()) - 1; i > 0; --i) {
            const int64_t j = static_cast<int64_t>(runner_rng.bounded_uint32(static_cast<uint32_t>(i)));
            std::swap(slots[static_cast<size_t>(i)], slots[static_cast<size_t>(j)]);
        }
        metadata_[py::str("native_runtime_numpy_runner_state")] = pcg64_state_to_py(runner_rng.state());
        return slots;
    }

    void refresh_agent_ids_by_alive_order_cpu() {
        const auto active_identity = active_identity_rows_exact(false);
        tensors_["agent_ids_by_alive_order"] = active_identity.agent_ids;
        tensors_["agent_id_to_slot_agent_ids"] = active_identity.agent_ids;
        tensors_["agent_id_to_slot_slots"] = active_identity.slots;
    }

    py::dict spawn_food_flat_uniform_weighted_cpu() {
        py::dict out;
        out["schema_version"] = "cxxbackbone26b_flat_food_spawn_v1";
        out["executed"] = false;
        out["spawn_attempts"] = static_cast<int64_t>(0);
        out["spawned_rows"] = static_cast<int64_t>(0);
        if (tensors_.find("food_grid") == tensors_.end()) {
            return out;
        }
        auto food_grid = tensors_.at("food_grid");
        TORCH_CHECK(!food_grid.is_cuda(), "flat food spawn requires CPU food_grid");
        TORCH_CHECK(food_grid.scalar_type() == torch::kInt32, "food_grid must be int32");
        const int64_t height = food_grid.size(0);
        const int64_t width = food_grid.size(1);
        const int64_t cell_count = height * width;
        if (height <= 0 || width <= 0 || cell_count <= 0) {
            return out;
        }
        const int64_t max_food = std::max<int64_t>(0, meta_int(metadata_, "max_food", 0));
        const double base = meta_double(metadata_, "food_spawn_per_step", 0.0);
        const double spawn_mult = meta_double(metadata_, "food_spawn_mult", 1.0);
        const int64_t eff = static_cast<int64_t>(std::llround(base * spawn_mult));
        if (max_food <= 0 || eff <= 0) {
            return out;
        }
        auto grid_a = food_grid.accessor<int32_t, 2>();
        int64_t current_food = 0;
        for (int64_t y = 0; y < height; ++y) {
            for (int64_t x = 0; x < width; ++x) {
                if (grid_a[y][x] == FOOD) {
                    current_food += 1;
                }
            }
        }
        if (current_food >= max_food) {
            return out;
        }
        const int64_t to_spawn = std::min<int64_t>(eff, max_food - current_food);
        if (to_spawn <= 0) {
            return out;
        }
        Pcg64State food_numpy_state;
        const bool env_policy_alias = meta_bool(metadata_, "native_runtime_env_policy_numpy_alias", false);
        if (env_policy_alias) {
            const bool birth_spawn_state_present = metadata_.contains("native_runtime_numpy_birth_spawn_env_state");
            if (birth_spawn_state_present) {
                food_numpy_state = meta_pcg64_state(metadata_, "native_runtime_numpy_birth_spawn_env_state");
                TORCH_CHECK(
                    food_numpy_state.valid,
                    "flat food spawn birth-spawn/env PCG64 state is present but invalid"
                );
            }
        }
        if (!food_numpy_state.valid) {
            food_numpy_state = meta_pcg64_state(metadata_, "native_runtime_numpy_policy_state");
        }
        TORCH_CHECK(food_numpy_state.valid, "flat food spawn requires serialized PCG64 food RNG state");
        Pcg64 food_rng(food_numpy_state);
        py::list positions;
        py::list attempts;
        py::list attempt_rows;
        out["mode"] = "flat_uniform";
        int64_t placed = 0;
        int64_t tries = 0;
        int64_t rng_draws = 0;
        const bool enable_biomes = meta_bool(metadata_, "enable_biomes", false);
        if (enable_biomes && tensors_.find("biome_grid") != tensors_.end()) {
            out["mode"] = "biome_unweighted";
            auto biome_grid = tensors_.at("biome_grid");
            TORCH_CHECK(!biome_grid.is_cuda(), "flat biome food spawn requires CPU biome_grid");
            TORCH_CHECK(biome_grid.scalar_type() == torch::kInt32, "biome_grid must be int32");
            TORCH_CHECK(biome_grid.size(0) == height && biome_grid.size(1) == width, "biome_grid shape must match food_grid");
            auto biome_a = biome_grid.accessor<int32_t, 2>();
            std::vector<int64_t> safe_cells;
            std::vector<int64_t> wild_cells;
            safe_cells.reserve(static_cast<size_t>(cell_count));
            wild_cells.reserve(static_cast<size_t>(cell_count));
            for (int64_t y = 0; y < height; ++y) {
                for (int64_t x = 0; x < width; ++x) {
                    const int64_t idx = y * width + x;
                    if (biome_a[y][x] == 0) {
                        safe_cells.push_back(idx);
                    } else {
                        wild_cells.push_back(idx);
                    }
                }
            }
            double safe_mult = meta_double(metadata_, "biome_safe_food_mult", 1.0);
            double wild_mult = meta_double(metadata_, "biome_wild_food_mult", 1.0);
            if (safe_cells.empty()) {
                safe_mult = 0.0;
            }
            if (wild_cells.empty()) {
                wild_mult = 0.0;
            }
            double safe_weight = static_cast<double>(safe_cells.size()) * safe_mult;
            double wild_weight = static_cast<double>(wild_cells.size()) * wild_mult;
            double denom = safe_weight + wild_weight;
            if (denom <= 1.0e-12) {
                safe_weight = static_cast<double>(safe_cells.size());
                wild_weight = static_cast<double>(wild_cells.size());
                denom = safe_weight + wild_weight;
            }
            if (denom > 1.0e-12) {
                int64_t n_safe = python_round_to_int64(static_cast<double>(to_spawn) * (safe_weight / denom));
                n_safe = std::max<int64_t>(0, std::min<int64_t>(to_spawn, n_safe));
                const int64_t n_wild = to_spawn - n_safe;
                out["biome_safe_cells"] = static_cast<int64_t>(safe_cells.size());
                out["biome_wild_cells"] = static_cast<int64_t>(wild_cells.size());
                out["biome_spawn_safe"] = n_safe;
                out["biome_spawn_wild"] = n_wild;
                auto spawn_in_cells = [&](const std::vector<int64_t>& cells, const int64_t n, const int64_t group_code) {
                    if (n <= 0 || cells.empty()) {
                        return;
                    }
                    int64_t local_placed = 0;
                    int64_t local_tries = 0;
                    const int64_t max_tries = std::max<int64_t>(50, n * 6);
                    while (local_placed < n && local_tries < max_tries) {
                        local_tries += 1;
                        const int64_t selected_j = pcg64_numpy_int64_integer(
                            food_rng,
                            static_cast<int64_t>(cells.size())
                        );
                        rng_draws += 1;
                        const int64_t cell = cells[static_cast<size_t>(selected_j)];
                        const int64_t y = cell / width;
                        const int64_t x = cell % width;
                        attempts.append(py::make_tuple(y, x));
                        attempt_rows.append(py::make_tuple(group_code, static_cast<int64_t>(selected_j), y, x, grid_a[y][x] == FOOD ? 1 : 0));
                        if (grid_a[y][x] != FOOD) {
                            grid_a[y][x] = FOOD;
                            placed += 1;
                            local_placed += 1;
                            positions.append(py::make_tuple(y, x));
                        }
                    }
                    tries += local_tries;
                };
                spawn_in_cells(safe_cells, n_safe, 0);
                spawn_in_cells(wild_cells, n_wild, 1);
            }
        } else {
            // Flat runners always carry the default positive density map, so
            // FoodMixin uses weighted choice over flat cells and retries
            // collisions until it places the requested count or exhausts the
            // bounded attempt budget.
            const int64_t max_tries = std::max<int64_t>(80, to_spawn * 10);
            while (placed < to_spawn && tries < max_tries) {
                tries += 1;
                int64_t idx = static_cast<int64_t>(
                    std::floor(food_rng.double01() * static_cast<double>(cell_count))
                );
                rng_draws += 1;
                if (idx < 0) {
                    idx = 0;
                } else if (idx >= cell_count) {
                    idx = cell_count - 1;
                }
                const int64_t y = idx / width;
                const int64_t x = idx % width;
                attempts.append(py::make_tuple(y, x));
                attempt_rows.append(py::make_tuple(2, idx, y, x, grid_a[y][x] == FOOD ? 1 : 0));
                if (grid_a[y][x] != FOOD) {
                    grid_a[y][x] = FOOD;
                    placed += 1;
                    positions.append(py::make_tuple(y, x));
                }
            }
        }
        food_numpy_state = food_rng.state();
        metadata_[py::str("native_runtime_numpy_policy_state")] = pcg64_state_to_py(food_numpy_state);
        if (meta_bool(metadata_, "native_runtime_env_policy_numpy_alias", false)) {
            metadata_[py::str("native_runtime_numpy_env_state")] = pcg64_state_to_py(food_numpy_state);
            // A persisted native sidecar already contains this alias, while a
            // reference sidecar reconstructs it from env state.  Refresh it on
            // tick zero too so both routes start birth placement after the same
            // food-spawn draws.
            metadata_[py::str("native_runtime_numpy_birth_spawn_env_state")] = pcg64_state_to_py(food_numpy_state);
            metadata_[py::str("native_runtime_rng_state")] = static_cast<int64_t>(food_numpy_state.state & 0x7fffffffffffffffULL);
        }
        out["executed"] = true;
        out["spawn_attempts"] = tries;
        out["spawned_rows"] = placed;
        out["attempts"] = attempts;
        out["attempt_rows"] = attempt_rows;
        out["positions"] = positions;
        add_rng_manager_stream_index("policy", "np", rng_draws);
        return out;
    }

    int64_t sync_patch_spawned_food_to_amount_exact() {
        TORCH_CHECK(tensors_.find("food_grid") != tensors_.end(), "Patch spawn sync requires food_grid");
        TORCH_CHECK(tensors_.find("patch_food_amount") != tensors_.end(), "Patch spawn sync requires patch_food_amount");
        auto food_grid = tensors_.at("food_grid");
        auto patch_food = tensors_.at("patch_food_amount");
        TORCH_CHECK(!food_grid.is_cuda() && !patch_food.is_cuda(), "Patch spawn sync requires CPU tensors");
        TORCH_CHECK(food_grid.scalar_type() == torch::kInt32, "food_grid must be int32");
        TORCH_CHECK(patch_food.scalar_type() == torch::kFloat32, "patch_food_amount must be float32");
        TORCH_CHECK(food_grid.sizes() == patch_food.sizes(), "food_grid and patch_food_amount must align");
        auto grid_a = food_grid.accessor<int32_t, 2>();
        auto amount_a = patch_food.accessor<float, 2>();
        const int64_t height = food_grid.size(0);
        const int64_t width = food_grid.size(1);
        const float threshold = static_cast<float>(meta_double(metadata_, "patch_food_presence_threshold", 0.5));
        const float initial = static_cast<float>(
            meta_double(
                metadata_,
                "patch_food_amount_initial_food_cell_value",
                meta_double(metadata_, "patch_food_amount_max", 1.0)
            )
        );
        int64_t synced = 0;
        for (int64_t y = 0; y < height; ++y) {
            for (int64_t x = 0; x < width; ++x) {
                if (grid_a[y][x] == FOOD && amount_a[y][x] <= threshold) {
                    amount_a[y][x] = initial;
                    synced += 1;
                }
            }
        }
        for (int64_t y = 0; y < height; ++y) {
            for (int64_t x = 0; x < width; ++x) {
                grid_a[y][x] = amount_a[y][x] > threshold ? FOOD : EMPTY;
            }
        }
        return synced;
    }

    int64_t consume_policy_env_chem_noise_cpu(const int64_t samples) {
        if (samples <= 0) {
            return 0;
        }
        if (meta_bool(metadata_, "native_runtime_env_policy_numpy_alias", false)) {
            Pcg64State spawn_env_state = meta_pcg64_state(metadata_, "native_runtime_numpy_birth_spawn_env_state");
            if (!spawn_env_state.valid) {
                spawn_env_state = meta_pcg64_state(metadata_, "native_runtime_numpy_env_state");
            }
            TORCH_CHECK(spawn_env_state.valid, "policy/env chemistry noise requires serialized PCG64 env RNG state");
            Pcg64 spawn_env_rng(spawn_env_state);
            pcg64_consume_numpy_standard_normal(spawn_env_rng, samples);
            metadata_[py::str("native_runtime_numpy_birth_spawn_env_state")] = pcg64_state_to_py(spawn_env_rng.state());

            Pcg64State policy_numpy_state = meta_pcg64_state(metadata_, "native_runtime_numpy_env_state");
            TORCH_CHECK(policy_numpy_state.valid, "policy/env chemistry noise requires serialized PCG64 env RNG state");
            Pcg64 policy_rng(policy_numpy_state);
            pcg64_consume_numpy_standard_normal(policy_rng, samples);
            policy_numpy_state = policy_rng.state();
            metadata_[py::str("native_runtime_numpy_policy_state")] = pcg64_state_to_py(policy_numpy_state);
            metadata_[py::str("native_runtime_numpy_env_state")] = pcg64_state_to_py(policy_numpy_state);
            metadata_[py::str("native_runtime_rng_state")] = static_cast<int64_t>(policy_numpy_state.state & 0x7fffffffffffffffULL);
            return samples;
        }
        Pcg64State env_numpy_state = meta_pcg64_state(metadata_, "native_runtime_numpy_env_state");
        TORCH_CHECK(env_numpy_state.valid, "policy/env chemistry noise requires serialized PCG64 env RNG state");
        Pcg64 env_rng(env_numpy_state);
        pcg64_consume_numpy_standard_normal(env_rng, samples);
        env_numpy_state = env_rng.state();
        metadata_[py::str("native_runtime_numpy_env_state")] = pcg64_state_to_py(env_numpy_state);
        metadata_[py::str("native_runtime_numpy_birth_spawn_env_state")] = pcg64_state_to_py(env_numpy_state);
        metadata_[py::str("native_runtime_rng_state")] = static_cast<int64_t>(env_numpy_state.state & 0x7fffffffffffffffULL);
        return samples;
    }

    int64_t apply_chemistry_update_exact(const std::vector<int64_t>& ordered_slots) {
        const int64_t samples = static_cast<int64_t>(ordered_slots.size()) * 2;
        if (samples <= 0) {
            return 0;
        }
        if (tensors_.find("chemistry") == tensors_.end()) {
            return consume_policy_env_chem_noise_cpu(samples);
        }

        auto chemistry = tensors_.at("chemistry");
        auto energy = tensors_.at("energy");
        auto health = tensors_.at("health");
        auto injury = tensors_.at("injury");
        auto drives = tensors_.at("drives");
        auto alive_mask = tensors_.at("alive_mask");
        TORCH_CHECK(!chemistry.is_cuda(), "chemistry update requires CPU chemistry");
        TORCH_CHECK(chemistry.scalar_type() == torch::kFloat32, "chemistry must be float32");
        TORCH_CHECK(chemistry.dim() == 2 && chemistry.size(1) >= 6, "chemistry must be [slots,6]");
        TORCH_CHECK(!energy.is_cuda() && !health.is_cuda() && !injury.is_cuda(), "chemistry update requires CPU physiology");
        TORCH_CHECK(!drives.is_cuda() && !alive_mask.is_cuda(), "chemistry update requires CPU drives and alive mask");

        const bool env_policy_alias = meta_bool(metadata_, "native_runtime_env_policy_numpy_alias", false);
        if (env_policy_alias) {
            Pcg64State spawn_env_state = meta_pcg64_state(metadata_, "native_runtime_numpy_birth_spawn_env_state");
            if (!spawn_env_state.valid) {
                spawn_env_state = meta_pcg64_state(metadata_, "native_runtime_numpy_env_state");
            }
            TORCH_CHECK(spawn_env_state.valid, "chemistry update requires serialized birth-spawn env RNG state");
            Pcg64 spawn_env_rng(spawn_env_state);
            pcg64_consume_numpy_standard_normal(spawn_env_rng, samples);
            metadata_[py::str("native_runtime_numpy_birth_spawn_env_state")] = pcg64_state_to_py(spawn_env_rng.state());
        }

        Pcg64State policy_numpy_state = env_policy_alias
            ? meta_pcg64_state(metadata_, "native_runtime_numpy_env_state")
            : meta_pcg64_state(metadata_, "native_runtime_numpy_policy_state");
        const bool use_policy_state = !env_policy_alias && policy_numpy_state.valid;
        if (!policy_numpy_state.valid && !env_policy_alias) {
            policy_numpy_state = meta_pcg64_state(metadata_, "native_runtime_numpy_env_state");
        }
        TORCH_CHECK(policy_numpy_state.valid, "chemistry update requires serialized PCG64 policy RNG state");
        Pcg64 policy_rng(policy_numpy_state);
        const std::vector<float> noise = pcg64_numpy_standard_normal_float32(policy_rng, samples);
        policy_numpy_state = policy_rng.state();
        if (use_policy_state || env_policy_alias) {
            metadata_[py::str("native_runtime_numpy_policy_state")] = pcg64_state_to_py(policy_numpy_state);
        }
        if (env_policy_alias || !use_policy_state) {
            metadata_[py::str("native_runtime_numpy_env_state")] = pcg64_state_to_py(policy_numpy_state);
            metadata_[py::str("native_runtime_rng_state")] = static_cast<int64_t>(
                policy_numpy_state.state & 0x7fffffffffffffffULL
            );
        }

        auto chemistry_a = chemistry.accessor<float, 2>();
        auto energy_a = energy.accessor<float, 1>();
        auto health_a = health.accessor<float, 1>();
        auto injury_a = injury.accessor<float, 1>();
        auto drives_a = drives.accessor<float, 2>();
        auto alive_a = alive_mask.accessor<bool, 1>();
        const double max_energy = static_cast<double>(static_cast<float>(meta_double(metadata_, "max_energy", 1.0)));
        const double start_health = static_cast<double>(static_cast<float>(meta_double(metadata_, "start_health", 1.0)));
        auto chem_clamp01 = [](const double value) -> double {
            if (value <= 0.0) {
                return 0.0;
            }
            if (value >= 1.0) {
                return 1.0;
            }
            return value;
        };
        for (size_t row = 0; row < ordered_slots.size(); ++row) {
            const int64_t slot = ordered_slots[row];
            if (slot < 0 || slot >= chemistry.size(0) || !alive_a[slot]) {
                continue;
            }
            const double energy_n = chem_clamp01(static_cast<double>(energy_a[slot]) / max_energy);
            const double health_n = chem_clamp01(static_cast<double>(health_a[slot]) / start_health);
            const double injury_n = chem_clamp01(static_cast<double>(injury_a[slot]) / start_health);
            const double stress = chem_clamp01(
                0.55 * injury_n
                + 0.30 * static_cast<double>(drives_a[slot][1])
                + 0.15 * (1.0 - energy_n)
            );
            double energy_store = static_cast<double>(chemistry_a[slot][0]);
            double repair = static_cast<double>(chemistry_a[slot][1]);
            double acute = static_cast<double>(chemistry_a[slot][2]);
            double chronic = static_cast<double>(chemistry_a[slot][3]);
            double reg1 = static_cast<double>(chemistry_a[slot][4]);
            double reg2 = static_cast<double>(chemistry_a[slot][5]);
            const double acute_target = chem_clamp01(
                1.25 * injury_n + 0.45 * stress + 0.20 * (1.0 - health_n)
            );
            acute = chem_clamp01(acute + 0.50 * (acute_target - acute) + 0.03 * reg1);
            const double chronic_target = chem_clamp01(0.75 * chronic + 0.25 * acute);
            chronic = chem_clamp01(chronic + 0.07 * (chronic_target - chronic));
            energy_store = chem_clamp01(energy_store + 0.03 * energy_n - 0.02 * stress - 0.01 * acute);
            repair = chem_clamp01(repair + 0.04 * energy_n - 0.03 * acute - 0.01 * chronic);
            const size_t noise_index = row * 2;
            reg1 = chem_clamp01(
                0.92 * reg1 + 0.08 * (1.0 - acute) + 0.01 * static_cast<double>(noise[noise_index])
            );
            reg2 = chem_clamp01(
                0.97 * reg2 + 0.03 * chronic + 0.01 * static_cast<double>(noise[noise_index + 1])
            );
            const double acute_resolve = std::min(acute, 0.10 * repair + 0.04 * energy_store);
            acute = chem_clamp01(acute - acute_resolve);
            chronic = chem_clamp01(chronic + 0.25 * acute - 0.002 * repair);
            chemistry_a[slot][0] = static_cast<float>(energy_store);
            chemistry_a[slot][1] = static_cast<float>(repair);
            chemistry_a[slot][2] = static_cast<float>(acute);
            chemistry_a[slot][3] = static_cast<float>(chronic);
            chemistry_a[slot][4] = static_cast<float>(reg1);
            chemistry_a[slot][5] = static_cast<float>(reg2);
        }
        return samples;
    }

