    void project_action_cache_next_after_service_cpu() {
        auto action_cache_token = tensors_.at("action_cache_token");
        auto action_cache_cursor = tensors_.at("action_cache_cursor");
        auto action_cache_next = tensors_.at("action_cache_next");
        auto action_cache_actions = tensors_.at("action_cache_actions");
        TORCH_CHECK(!action_cache_token.is_cuda(), "action cache projection requires CPU tensors");
        TORCH_CHECK(!action_cache_cursor.is_cuda(), "action cache projection requires CPU tensors");
        TORCH_CHECK(!action_cache_next.is_cuda(), "action cache projection requires CPU tensors");
        TORCH_CHECK(!action_cache_actions.is_cuda(), "action cache projection requires CPU tensors");
        TORCH_CHECK(action_cache_actions.dim() == 2, "action cache projection requires [slots,stride]");
        const int64_t width = action_cache_actions.size(1);
        TORCH_CHECK(width > 0, "action cache projection requires positive stride width");
        auto token_a = action_cache_token.accessor<int64_t, 1>();
        auto cursor_a = action_cache_cursor.accessor<int32_t, 1>();
        auto next_a = action_cache_next.accessor<int32_t, 1>();
        auto actions_a = action_cache_actions.accessor<int32_t, 2>();
        for (int64_t slot = 0; slot < action_cache_next.size(0); ++slot) {
            const int32_t cursor = cursor_a[slot];
            if (token_a[slot] < 0 || cursor < 0) {
                next_a[slot] = -1;
                continue;
            }
            const int64_t projected_index = cursor < width ? cursor : width - 1;
            next_a[slot] = actions_a[slot][projected_index];
        }
    }

    bool has_alive_action_cache_miss_cpu() const {
        if (
            tensors_.find("action_cache_next") == tensors_.end()
            || tensors_.find("action_cache_cursor") == tensors_.end()
        ) {
            return true;
        }
        auto action_cache_next = tensors_.at("action_cache_next");
        auto action_cache_cursor = tensors_.at("action_cache_cursor");
        TORCH_CHECK(!action_cache_next.is_cuda() && !action_cache_cursor.is_cuda(), "action cache miss check requires CPU cache tensors");
        TORCH_CHECK(action_cache_next.scalar_type() == torch::kInt32, "action_cache_next must be int32");
        TORCH_CHECK(action_cache_cursor.scalar_type() == torch::kInt32, "action_cache_cursor must be int32");
        auto next_a = action_cache_next.accessor<int32_t, 1>();
        auto cursor_a = action_cache_cursor.accessor<int32_t, 1>();
        const auto slots = alive_slots_sorted_by_agent_id();
        for (const int64_t slot : slots) {
            if (next_a[slot] < 0 || cursor_a[slot] <= 0) {
                return true;
            }
        }
        return false;
    }

    static int32_t action_at_slot(const torch::Tensor& actions_by_slot, const int64_t slot) {
        auto actions_a = actions_by_slot.accessor<int32_t, 1>();
        int32_t action = actions_a[slot];
        if (action < 0 || action > ACT_ATTACK) {
            action = ACT_REST;
        }
        return action;
    }

    float base_action_cost(const int32_t action) const {
        float cost = static_cast<float>(meta_double(metadata_, "move_cost", 1.0));
        if (action == ACT_GATHER) {
            cost = static_cast<float>(meta_double(metadata_, "gather_cost", 1.0));
        } else if (action == ACT_REST) {
            cost = static_cast<float>(meta_double(metadata_, "rest_cost", 0.25));
        } else if (action == ACT_ATTACK) {
            cost = static_cast<float>(meta_double(metadata_, "attack_cost", 0.60));
        }
        const double action_mult = meta_double(metadata_, "action_cost_mult", 1.0);
        if (action_mult != 1.0) {
            cost = static_cast<float>(static_cast<double>(cost) * action_mult);
        }
        const double rest_mult = meta_double(metadata_, "rest_cost_mult", 1.0);
        if (rest_mult != 1.0 && action == ACT_REST) {
            cost = static_cast<float>(static_cast<double>(cost) * rest_mult);
        }
        return cost;
    }

