        tensors["correctness"] = correctness_.clone();
        tensors["consequence_status"] = consequence_status_.clone();
        tensors["task_rng_state"] = task_rng_state_.clone();
        tensors["task_rng_cursor"] = task_rng_cursor_.clone();
        py::dict metadata;
        metadata["schema_version"] = "eiel_gmnw_cpu_owner_checkpoint_v1";
