        metadata["task_seed"] = config_.task_seed;
        metadata["grace_generation_count"] = config_.grace_generation_count;
        metadata["severe_generation_count"] = config_.severe_generation_count;
        metadata["grace_damage_fraction"] = config_.grace_damage_fraction;
        metadata["severe_damage_fraction"] = config_.severe_damage_fraction;
        metadata["lethal_damage_fraction"] = config_.lethal_damage_fraction;
